"""Pinned BSD-licensed NASM adapter. Input is generated by aa_program, not CTs."""

from __future__ import annotations

import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import time

from .lua_work_budget import remaining_seconds, broker_checkpoint


NASM_VERSION = "3.02"
NASM_WIN64_SHA256 = "04ec2385879f7e1c45dbe76c4020970555de48eeb97c23f59620ede061328f51"
MAX_ASSEMBLY_BYTES = 4 * 1024 * 1024


class AssemblyError(ValueError):
    pass


def _remove_temp_dir_quietly(root: Path, *, attempts: int = 5, delay: float = 0.1) -> bool:
    """Best-effort removal of one NASM working directory.

    Under Proton/SteamOS the Wine VFS plus FUSE layers can keep a directory
    pinned (ERROR_SHARING_VIOLATION / WinError 32) briefly after a child
    process exits, so the plain ``TemporaryDirectory`` rmtree aborts the
    trainer. Delete the files first, then retry the directory removal; a
    persistent failure must never raise because the temp area is transient.
    """
    for attempt in range(attempts):
        try:
            for child in root.iterdir():
                if child.is_file() or child.is_symlink():
                    child.unlink()
                else:
                    shutil.rmtree(child, ignore_errors=True)
            root.rmdir()
            return True
        except OSError:
            if attempt + 1 < attempts:
                time.sleep(delay)
    if sys.stderr is not None:
        print(f"ct2trainer: could not remove temporary directory {root}", file=sys.stderr)
    return False


def find_nasm() -> Path:
    candidates = []
    override = os.environ.get("CT2TRAINER_NASM")
    if override:
        candidates.append(Path(override))
    if getattr(sys, "frozen", False):
        candidates.extend([Path(getattr(sys, "_MEIPASS", Path(sys.executable).parent)) / "native-tools" / "nasm.exe", Path(sys.executable).parent / "native-tools" / "nasm.exe"])
    root = Path(__file__).resolve().parents[3]
    candidates.append(root / ".tools" / "native" / "nasm-3.02" / "nasm-3.02" / "nasm.exe")
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    raise AssemblyError("Pinned NASM 3.02 is unavailable; restore the archived native dependency.")


class NasmAssembler:
    def __init__(self, executable: str | Path | None = None, *, expected_sha256: str = NASM_WIN64_SHA256):
        self.executable = Path(executable) if executable is not None else find_nasm()
        self.expected_sha256 = expected_sha256
        self._verify()

    def _verify(self):
        try:
            digest = hashlib.sha256(self.executable.read_bytes()).hexdigest()
        except OSError as exc:
            raise AssemblyError("Cannot read the pinned NASM executable.") from exc
        if digest != self.expected_sha256:
            raise AssemblyError("NASM executable does not match its pinned SHA-256.")

    def assemble(self, source: str) -> bytes:
        if not isinstance(source, str) or len(source.encode("ascii", "strict")) > MAX_ASSEMBLY_BYTES:
            raise AssemblyError("Generated assembly exceeds its size bound.")
        broker_checkpoint()
        self._verify()
        root = Path(tempfile.mkdtemp(prefix="ct2trainer-nasm-"))
        try:
            assembly = root / "program.asm"
            output = root / "program.bin"
            assembly.write_text(source, encoding="ascii")
            try:
                # cwd stays the temp root, never the throwaway subdirectory:
                # a child CWD inside it is exactly what Proton/FUSE keeps
                # pinned after the child exits (WinError 32 on rmtree).
                result = subprocess.run([str(self.executable.resolve()), "-f", "bin", "-w+error=all", "-o", str(output), str(assembly)], cwd=root.parent, capture_output=True, timeout=remaining_seconds(10), check=False, creationflags=0x08000000 if os.name == "nt" else 0)
            except (OSError, subprocess.TimeoutExpired) as exc:
                raise AssemblyError("NASM failed to start or exceeded its 10-second limit.") from exc
            broker_checkpoint()
            if result.returncode:
                diagnostic = result.stderr.decode("utf-8", "replace")[:4096]
                raise AssemblyError("NASM rejected the program: " + diagnostic)
            if not output.is_file() or output.stat().st_size > MAX_ASSEMBLY_BYTES:
                raise AssemblyError("NASM output is absent or exceeds its size bound.")
            return output.read_bytes()
        finally:
            _remove_temp_dir_quietly(root)
